use super::*;
use semio_os_flow_host_session::invocation_publication::*;
use semio_framework_value::retained_clone::RetainedCloneGrant;
use semio_framework_value::retirement::controlled::ControlledRetirement;
fn observe<T>(work:impl FnOnce()->T)->(T,usize,usize){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(work);(value,heap.requested_bytes,heap.released_bytes)}
fn origin(row:&serde_json::Value)->FlowInvocationOrigin{FlowInvocationOrigin{window_id:row["windowId"].as_str().unwrap().into(),window_kind_id:row["windowKindId"].as_str().unwrap().into(),neuron_id:row["neuronId"].as_str().unwrap().into(),extension_id:row["extensionId"].as_str().unwrap().into(),operator_id:row["operatorId"].as_str().unwrap().into(),node_hash:row["nodeHash"].as_u64().unwrap(),input_json:row["inputJson"].as_str().unwrap().into(),dependency_json:row["dependencyJson"].as_str().unwrap().into(),operator_version:row["operatorVersion"].as_str().unwrap().into(),outer_node_hash:None,preview_source:None}}
#[test]
fn original_invocation_identity_preserves_actual_operation_and_paid_text(){
 let corpus:serde_json::Value=serde_json::from_str(read_node("📤️publication/📡️invocation/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in corpus["identities"].as_array().unwrap(){let operation=row["operationId"].as_str().unwrap().parse::<u64>().unwrap();for copy in [1,3,64]{for cancel in [None,Some(0),Some(3),Some(9),Some(37)]{
  let(mut source,born,free)=observe(||FlowInvocationIdentity::new(operation));assert_eq!((born,free),(0,0));let(mut births,mut releases)=(0,0);for turn in 0..100{if cancel==Some(turn)||source.complete(){break}let d=source.demands();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let(p,born,free)=observe(||source.step(RetainedCloneGrant{maximum_items:0,..grant}).unwrap());assert_eq!(p,Default::default());assert_eq!((born,free),(0,0));let(p,born,free)=observe(||source.step(grant).unwrap());assert!(p.fits(grant));assert_eq!((born,free),(p.retained_capacity_bytes,p.released_bytes));births+=born;releases+=free;assert_eq!(source.source(),operation);}if cancel.is_none(){assert!(source.complete());assert_eq!(source.text(),row["cancellationId"].as_str());}
  let(mut owner,born,free)=observe(||ControlledRetirement::new(source).unwrap_or_else(|_|unreachable!()));assert_eq!((born,free),(0,0));let mut idle=0;for _ in 0..100000{if owner.terminal_is_empty(){break}let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(copy).unwrap(),maximum_release_bytes:owner.next_release_byte_demand().unwrap(),maximum_depth:owner.next_depth_demand().unwrap()};let(step,born,free)=observe(||owner.step(grant).unwrap());let p=step.progress();assert!(p.fits(grant));assert_eq!((born,free),(p.retained_capacity_bytes,p.released_bytes));births+=born;releases+=free;if p==Default::default(){idle+=1}else{idle=0}assert!(idle<64);}assert!(owner.terminal_is_empty());assert_eq!(births,releases);assert_eq!(observe(||drop(owner)),((),0,0));
 }}}
}
#[test]
fn original_invocation_ledger_preserves_sources_and_allocation_receipts(){
 let corpus:serde_json::Value=serde_json::from_str(read_node("📤️publication/📡️invocation/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for copy in [1,3,64]{for cancel in [None,Some(0),Some(1),Some(3)]{
  let((mut session,mut accepted),born,free)=observe(||(FlowEvalSession::new(),corpus["cases"].as_array().unwrap().iter().map(|row|FlowInvocationOriginLease::from_cold(origin(&row["source"]))).collect::<Vec<_>>()));let original=born-free;let pointers:Vec<_>=accepted.iter().map(|source|source.input_json.as_ptr()).collect();let(mut births,mut releases)=(0,0);let mut turn=0;
  while !accepted.is_empty(){if cancel==Some(turn){break}let mut idle=0;while session.invocation_origin_reserve_pending(){let d=session.next_invocation_origin_reserve_demands(copy).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let(p,born,free)=observe(||session.reserve_invocation_origin_step(RetainedCloneGrant{maximum_items:0,..grant}).unwrap());assert_eq!(p,Default::default());assert_eq!((born,free),(0,0));let(p,born,free)=observe(||session.reserve_invocation_origin_step(grant).unwrap());assert!(p.fits(grant));assert_eq!((born,free),(p.retained_capacity_bytes,p.released_bytes));births+=born;releases+=free;if p==Default::default(){idle+=1}else{idle=0}assert!(idle<64);}
   let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};let original_source=accepted.pop().unwrap();let input=original_source.input_json.as_ptr();let(original_source,born,free)=observe(||{let(error,source)=session.retain_invocation_origin_step(original_source,RetainedCloneGrant{maximum_items:0,..grant}).err().unwrap();assert_eq!(error.retained_progress(),Default::default());source});assert_eq!((born,free),(0,0));assert_eq!(original_source.input_json.as_ptr(),input);let(p,born,free)=observe(||session.retain_invocation_origin_step(original_source,grant).unwrap_or_else(|_|unreachable!()));assert_eq!(p.copied_bytes,0);assert_eq!((born,free),(0,0));turn+=1;
  }
  for index in 0..session.test_invocation_origin_count(){
   let source=session.invocation_origin_at(index).unwrap();let pointer=source as*const _;assert!(pointers.contains(&source.input_json.as_ptr()));let d=FlowEvalSession::invocation_origin_alias_demands();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:d.depth};let mut alias=None;
   for denied in [RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let(turn,born,free)=observe(||session.retain_invocation_origin_at(index,&mut alias,denied));assert_eq!((turn.work,born,free),(0,0,0));assert_eq!(turn.result.unwrap().progress(),Default::default());assert!(alias.is_none());}
   let stock=RetainedCloneGrant{maximum_items:65536,maximum_copy_bytes:128<<20,maximum_capacity_bytes:256<<20,maximum_release_bytes:512<<20,maximum_depth:4096};let mut caller=semio_framework_job::OriginalJobFixtureCaller::admit(semio_framework_job::OperationId(97146),semio_framework_job::Generation(17),stock,||Some(1000),1500,32768);
   let(_,born,free)=observe(||caller.turn(g,|cx|cx.with_original_work_loan(1,1500,|cx|{let turn=session.retain_invocation_origin_at(index,&mut alias,cx.retained_grant());semio_framework_job::receive_original_retained_work(cx,turn).map(|_|())})).unwrap());assert_eq!((born,free),(0,0));assert_eq!(caller.receipt().copied_bytes,d.copy_bytes);assert_eq!(&**alias.as_ref().unwrap()as*const _,pointer);
   let(mut close,born,free)=observe(||ControlledRetirement::new(alias).unwrap_or_else(|_|unreachable!()));assert_eq!((born,free),(0,0));for _ in 0..100000{if close.terminal_is_empty(){break}let d=close.selected_demand(4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let(_,born,free)=observe(||caller.turn(g,|cx|cx.with_original_work_loan(1,1500,|cx|{semio_framework_job::close_original_retained_step(cx,d,|g|{let result=close.step(g);semio_framework_value::RetainedWorkOutcome{result,work:close.last_turn_work()}})?;Ok(())})).unwrap());let p=caller.receipt();assert_eq!((born,free),(p.retained_capacity_bytes,p.released_bytes));births+=born;releases+=free;}assert!(close.terminal_is_empty());caller.retire(stock);
  }
  session.begin_close();let mut idle=0;for _ in 0..100000{if session.terminal_is_empty(){break}let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:session.next_close_capacity_byte_demand(copy).unwrap(),maximum_release_bytes:session.next_close_release_byte_demand().unwrap(),maximum_depth:session.next_close_depth_demand().unwrap()};let(step,born,free)=observe(||session.close_step(grant));let p=step.unwrap().progress();assert!(p.fits(grant));assert_eq!((born,free),(p.retained_capacity_bytes,p.released_bytes));births+=born;releases+=free;if p==Default::default(){idle+=1}else{idle=0}assert!(idle<64);}assert!(session.terminal_is_empty());assert_eq!(observe(||drop(session)),((),0,0));let(mut owner,born,free)=observe(||ControlledRetirement::new(accepted).unwrap_or_else(|_|unreachable!()));assert_eq!((born,free),(0,0));while !owner.terminal_is_empty(){let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(copy).unwrap(),maximum_release_bytes:owner.next_release_byte_demand().unwrap(),maximum_depth:owner.next_depth_demand().unwrap()};let(step,born,free)=observe(||owner.step(grant).unwrap());let p=step.progress();assert_eq!((born,free),(p.retained_capacity_bytes,p.released_bytes));births+=born;releases+=free;}assert_eq!(observe(||drop(owner)),((),0,0));assert_eq!(original+births,releases);
 }}
}

#[test]
fn original_window_key_matches_actual_str_hash_under_one_fuel_and_cancellation(){
 use std::hash::{Hash,Hasher};use semio_os_flow_host_session::FlowEvalWindowKeyWork;
 let fixture:serde_json::Value=serde_json::from_str(read_node("📤️publication/📡️invocation/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for row in fixture["windowKeys"].as_array().unwrap(){for stop in [None,Some(0),Some(1),Some(2)]{let word=row["word"].as_str().unwrap();let mut expected=std::collections::hash_map::DefaultHasher::new();word.hash(&mut expected);let mut work=FlowEvalWindowKeyWork::new();let stock=RetainedCloneGrant{maximum_items:65536,maximum_copy_bytes:128<<20,maximum_capacity_bytes:256<<20,maximum_release_bytes:512<<20,maximum_depth:4096};let mut caller=semio_framework_job::OriginalJobFixtureCaller::admit(semio_framework_job::OperationId(97146),semio_framework_job::Generation(17),stock,||Some(1000),1500,32768);let mut output=None;
  for turn in 0..200{if stop==Some(turn){caller.cancel().cancel_now();let(_,born,free)=observe(||caller.turn(stock,|cx|cx.with_original_work_loan(1,1500,|cx|{assert!(work.step(word,cx)?.is_none());Ok(())})).unwrap());assert_eq!((born,free),(0,0));assert_eq!(caller.receipt(),Default::default());break}let d=work.next_demands(word).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};let(_,born,free)=observe(||caller.turn(RetainedCloneGrant{maximum_items:0,..g},|cx|cx.with_original_work_loan(1,1500,|cx|{assert!(work.step(word,cx)?.is_none());Ok(())})).unwrap());assert_eq!((born,free),(0,0));assert_eq!(caller.receipt(),Default::default());let(_,born,free)=observe(||caller.turn(g,|cx|cx.with_original_work_loan(1,1500,|cx|{output=work.step(word,cx)?;Ok(())})).unwrap());assert_eq!((born,free),(0,0));assert!(caller.receipt().fits(g));if output.is_some(){break}}
  if stop.is_none(){assert_eq!(output.unwrap().fingerprint(),expected.finish())}work.begin_close();for _ in 0..200{if work.terminal_is_empty(){break}let d=work.close_demands();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:d.depth};let(_,born,free)=observe(||caller.turn(g,|cx|cx.with_original_work_loan(1,1500,|cx|{work.close_step(cx)?;Ok(())})).unwrap());assert_eq!((born,free),(0,0));assert!(caller.receipt().fits(g));}assert!(work.terminal_is_empty());caller.retire(stock);
 }}
}
